import sys

class Solution:
    def minDistance(self, a, b):
        sys.setrecursionlimit(10**6)
        def go(i, j):
            if i == 0:
                return j
            if j == 0:
                return i
            if a[i - 1] == b[j - 1]:
                return go(i - 1, j - 1)
            return 1 + min(go(i - 1, j - 1), go(i - 1, j), go(i, j - 1))
        return go(len(a), len(b))
